begin
  if (select count(*) from public.aos_catalogo_reconciliation_lineage_v1
      where reconciliation_code='CATALOG_SEP2026_V1' and entity_kind='SERVICE' and action='UPDATED_CURRENT')<>27
    then raise exception 'SEP26 slice 1 cumulative UPDATED_CURRENT mismatch'; end if;
  if (select count(*) from public.aos_catalogo_reconciliation_lineage_v1
      where reconciliation_code='CATALOG_SEP2026_V1' and entity_kind='SERVICE' and action='INSERTED_CURRENT')<>4
    then raise exception 'SEP26 slice 1 cumulative INSERTED_CURRENT mismatch'; end if;
